import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('tiempos-dificiles', 'A',
 [dict(t=365, e=395, titulo='La última generación', txt='Hermano, mire, de veras, con todo mi corazón, […] es lo que yo creo: creo que nosotros somos la última generación de cristianos sobre la tierra. Creo que […] estamos viendo los últimos días de la iglesia de Cristo acá. Lo creo desde muchos aspectos.'),
  dict(t=2526, e=2590, titulo='Un encuentro personal', txt='Cuando tuve ese impacto fue tan fuerte, hermano, que yo no lo quería ver, porque yo sentía que me estaba muriendo. Entonces, como pude, me salí de la visión y, hermano, yo sentí como que me hubieran agarrado la cabeza acá y me hubieran dicho: «Para esto te traje, papito, ¿verdad?». Y me vuelven a meter en la visión, hermano. Lo demás ya no se lo cuento; eso ya es personal entre el Señor y yo. Pero la cosa es que yo tuve un encuentro, hermano, como nunca lo he tenido. Eso me cambió. Yo salí del culto llorando, hermano. Eso me conmovió el corazón. Toda la frialdad que yo tenía se me había acabado. Todas mis faltas de orar se me habían terminado. Todo, hermano, se me acabó, porque tuve un encuentro con él, personal. Mire, como nunca lo había tenido. Yo había servido al Señor y otras cosas, pero nunca de esa manera.'),
  dict(t=3822, e=3886, titulo='Levantarse y renovar el pacto', txt='Lo importante no es si nos caemos o no del caballo. Lo importante es levantarse, hermano. Importante no es si fracasamos, porque todos fracasamos, hermano. Lo importante es levantarse del fracaso. Habla con tu Señor. Dile: «Yo necesito entrar en alianza contigo nuevamente. Yo necesito entrar en un pacto, la renovación de nuestro amor. […] Quiero amarte como tú te mereces, no como yo te lo doy; quiero amarte como tú te mereces, Señor, ser amado».')],
 [dict(t=866, txt='También dice la Biblia: «El gozo del Señor es mi fuerza». O sea que, si se va a menguar la fuerza, ¿qué es lo que va a menguar?'),
  dict(t=2328, txt='La relación con Dios no se arregla con privilegios.')],
 ['El gozo del Señor es nuestra fuerza. ¿Qué te está quitando el gozo, y con él la fuerza, en este tiempo?',
  '¿Hay algo en tu semana que ocupa el lugar que le corresponde al Señor? ¿Cómo lo ordenarías?',
  '«Lo importante es levantarse». ¿Qué fracaso necesitas dejar atrás para renovar tu pacto con Dios hoy?'])
